//! Bridges exchange-client Redis publications into live market state.
use futures_util::StreamExt;use score_engine::{calibrate_confidence,PerformanceFeedback};use std::time::{SystemTime,UNIX_EPOCH};use teloxide::prelude::*;use teloxide::types::ChatId;use crate::alarms::AlertPolicy;use crate::handlers::AppState;use crate::i18n;
fn now_millis()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis() as i64}
pub async fn run(redis_url:String,bot:Bot,state:AppState)->redis::RedisResult<()>{let client=redis::Client::open(redis_url)?;let mut pubsub=client.get_async_pubsub().await?;pubsub.psubscribe("candles:*").await?;pubsub.psubscribe("orderbook:*").await?;pubsub.psubscribe("funding:*").await?;pubsub.psubscribe("open_interest:*").await?;let mut messages=pubsub.on_message();while let Some(message)=messages.next().await{let channel=message.get_channel_name().to_string();let Ok(payload)=message.get_payload::<String>()else{continue};let score=if channel.starts_with("candles:"){serde_json::from_str::<shared::Candle>(&payload).ok().and_then(|x|state.market_state.ingest_candle(x))}else if channel.starts_with("orderbook:"){serde_json::from_str::<shared::OrderBookSnapshot>(&payload).ok().and_then(|x|state.market_state.ingest_order_book(x))}else if channel.starts_with("funding:"){serde_json::from_str::<shared::FundingRate>(&payload).ok().and_then(|x|state.market_state.ingest_funding_rate(x))}else if channel.starts_with("open_interest:"){serde_json::from_str::<shared::OpenInterest>(&payload).ok().and_then(|x|state.market_state.ingest_open_interest(x))}else{None};let Some(score)=score else{continue};for(telegram_id,threshold)in state.alarms.crossed(&score.symbol,score.value){notify_alarm(&bot,&state,telegram_id,&score,threshold).await;}if let Some(snapshot)=state.market_state.intelligence(&score.symbol){state.decision_history.push(&snapshot);let(calibrated,policy)=calibration_and_policy(&state,&snapshot).await;if let Some(ledger)=state.decision_ledger.as_ref(){if let Err(err)=ledger.append(&snapshot).await{tracing::warn!(error=%err,symbol=%snapshot.symbol,"failed to persist intelligence decision");}}let history_depth=state.decision_history.latest(&snapshot.symbol,200).len();tracing::debug!(symbol=%snapshot.symbol,history_depth,raw_confidence=snapshot.decision.confidence,calibrated_confidence=calibrated,min_confidence=policy.min_confidence,max_risk=policy.max_risk,cooldown_ms=policy.cooldown_ms,"intelligence decision recorded");let mut decision=snapshot.decision;decision.confidence=calibrated;if let Some(alert)=state.smart_alerts.evaluate_with_policy(&snapshot.symbol,&decision,now_millis(),policy){for telegram_id in state.alarms.subscribers(&snapshot.symbol){notify_smart_alert(&bot,&state,telegram_id,&snapshot,calibrated,policy).await;}tracing::info!(symbol=%alert.symbol,decision=?alert.decision,confidence=alert.confidence,risk=alert.risk,"adaptive smart intelligence alert delivered");}}}Ok(())}
async fn calibration_and_policy(state:&AppState,snapshot:&score_engine::IntelligenceSnapshot)->(f64,AlertPolicy){let Some(ledger)=state.decision_ledger.as_ref()else{return(snapshot.decision.confidence,AlertPolicy::default());};let Ok(Some(p))=ledger.performance(&snapshot.symbol,200).await else{return(snapshot.decision.confidence,AlertPolicy::default());};let calibrated=calibrate_confidence(snapshot.decision.confidence,PerformanceFeedback{samples:p.samples,avg_confidence:p.avg_confidence,avg_risk:p.avg_risk,avg_data_quality:p.avg_data_quality,avg_agreement:p.avg_agreement}).calibrated_confidence;let policy=AlertPolicy::adaptive(p.samples,p.avg_risk,p.avg_data_quality,p.avg_agreement);(calibrated,policy)}
async fn notify_alarm(bot:&Bot,state:&AppState,telegram_id:i64,score:&shared::Score,threshold:f64){let lang=match state.user_store.get(telegram_id).await{Some(user)=>user.language,None=>"en".into()};let body=i18n::t_args(&lang,"alarm-triggered",&[("symbol",score.symbol.clone()),("threshold",format!("{:.1}",threshold)),("score",format!("{:.1}",score.value))]);let text=i18n::with_footer(&lang,&body);if let Err(err)=bot.send_message(ChatId(telegram_id),text).await{tracing::warn!(error=%err,"failed to send alarm notification");}}
async fn notify_smart_alert(bot:&Bot,state:&AppState,telegram_id:i64,snapshot:&score_engine::IntelligenceSnapshot,calibrated_confidence:f64,policy:AlertPolicy){let lang=match state.user_store.get(telegram_id).await{Some(user)=>user.language,None=>"en".into()};let reasons=if snapshot.explanation.reasons.is_empty(){"-".into()}else{snapshot.explanation.reasons.join(", ")};let warnings=if snapshot.explanation.warnings.is_empty(){"-".into()}else{snapshot.explanation.warnings.join(", ")};let body=format!("BOLDTRACE Intelligence — {}\nDecision: {:?}\nConfidence: {:.1} (raw {:.1})\nRisk: {:.1}\nScore: {:.1}\nData quality: {:.1}\nPolicy: conf ≥ {:.1}, risk < {:.1}\nReasons: {}\nWarnings: {}",snapshot.symbol,snapshot.decision.decision,calibrated_confidence,snapshot.decision.confidence,snapshot.decision.risk,snapshot.score,snapshot.data_quality,policy.min_confidence,policy.max_risk,reasons,warnings);let text=i18n::with_footer(&lang,&body);if let Err(err)=bot.send_message(ChatId(telegram_id),text).await{tracing::warn!(error=%err,telegram_id,"failed to send smart intelligence alert");}}
